    // https://www.mql5.com/en/docs/marketinformation/symbolstotal
    virtual ::grpc::Status SymbolsTotal(::grpc::ServerContext* context, const ::mt5_term_api::SymbolsTotalRequest* request, ::mt5_term_api::SymbolsTotalReply* response);
