    virtual ::grpc::Status SymbolName(::grpc::ServerContext* context, const ::mt5_term_api::SymbolNameRequest* request, ::mt5_term_api::SymbolNameReply* response);
    // Selects a symbol in the Market Watch window or removes a symbol from the window
    // https://www.mql5.com/en/docs/marketinformation/symbolselect
    virtual ::grpc::Status SymbolSelect(::grpc::ServerContext* context, const ::mt5_term_api::SymbolSelectRequest* request, ::mt5_term_api::SymbolSelectReply* response);
