    // https://www.mql5.com/en/docs/marketinformation/symbolissynchronized
    virtual ::grpc::Status SymbolIsSynchronized(::grpc::ServerContext* context, const ::mt5_term_api::SymbolIsSynchronizedRequest* request, ::mt5_term_api::SymbolIsSynchronizedReply* response);
    // Returns the corresponding property of a specified symbol. Immediately returns the property value.
    // https://www.mql5.com/en/docs/marketinformation/symbolinfodouble
    virtual ::grpc::Status SymbolInfoDouble(::grpc::ServerContext* context, const ::mt5_term_api::SymbolInfoDoubleRequest* request, ::mt5_term_api::SymbolInfoDoubleReply* response);
    // Returns the corresponding property of a specified symbol. 
    // https://www.mql5.com/en/docs/marketinformation/symbolinfointeger
    virtual ::grpc::Status SymbolInfoInteger(::grpc::ServerContext* context, const ::mt5_term_api::SymbolInfoIntegerRequest* request, ::mt5_term_api::SymbolInfoIntegerReply* response);
    // Returns the corresponding property of a specified symbol. Immediately returns the property value
    // https://www.mql5.com/en/docs/marketinformation/symbolinfostring  
    virtual ::grpc::Status SymbolInfoString(::grpc::ServerContext* context, const ::mt5_term_api::SymbolInfoStringRequest* request, ::mt5_term_api::SymbolInfoStringReply* response);
    // Returns the margin rates depending on the order type and direction
