    virtual ::grpc::Status SymbolInfoMarginRate(::grpc::ServerContext* context, const ::mt5_term_api::SymbolInfoMarginRateRequest* request, ::mt5_term_api::SymbolInfoMarginRateReply* response);
    // The function returns current prices of a specified symbol in a variable of the MqlTick type
    // https://www.mql5.com/en/docs/marketinformation/symbolinfotick
    virtual ::grpc::Status SymbolInfoTick(::grpc::ServerContext* context, const ::mt5_term_api::SymbolInfoTickRequest* request, ::mt5_term_api::SymbolInfoTickRequestReply* response);
    // Allows receiving time of beginning and end of the specified quoting sessions for a specified symbol and day of week
    // https://www.mql5.com/en/docs/marketinformation/symbolinfosessionquote
    virtual ::grpc::Status SymbolInfoSessionQuote(::grpc::ServerContext* context, const ::mt5_term_api::SymbolInfoSessionQuoteRequest* request, ::mt5_term_api::SymbolInfoSessionQuoteReply* response);
    // Allows receiving time of beginning and end of the specified trading sessions for a specified symbol and day of week
    // https://www.mql5.com/en/docs/marketinformation/symbolinfosessiontrade
    virtual ::grpc::Status SymbolInfoSessionTrade(::grpc::ServerContext* context, const ::mt5_term_api::SymbolInfoSessionTradeRequest* request, ::mt5_term_api::SymbolInfoSessionTradeReply* response);
    // Provides opening of Depth of Market for a selected symbol, and subscribes for receiving notifications of the DOM changes
