    virtual ::grpc::Status MarketBookAdd(::grpc::ServerContext* context, const ::mt5_term_api::MarketBookAddRequest* request, ::mt5_term_api::MarketBookAddReply* response);
    // Provides closing of Depth of Market for a selected symbol, and cancels the subscription for receiving notifications of the DOM changes
    // https://www.mql5.com/en/docs/marketinformation/marketbookrelease
    virtual ::grpc::Status MarketBookRelease(::grpc::ServerContext* context, const ::mt5_term_api::MarketBookReleaseRequest* request, ::mt5_term_api::MarketBookReleaseReply* response);
    // Returns a structure array MqlBookInfo containing records of the Depth of Market of a specified symbol
