    virtual ::grpc::Status MarketBookGet(::grpc::ServerContext* context, const ::mt5_term_api::MarketBookGetRequest* request, ::mt5_term_api::MarketBookGetReply* response);
    // Returns a collection of a broker symbols
    virtual ::grpc::Status SymbolList(::grpc::ServerContext* context, const ::mt5_term_api::SymbolListRequest* request, ::mt5_term_api::SymbolListReply* response);
